"""
Build specs/Review_Data_Spec.xlsx - source-to-review mapping specification.

Inputs read from the code base so spec and implementation stay aligned:
  config/visit_schedule.csv           -> sheet "Visit Schedule"
  <spec_inputs>/checks.csv            -> sheet "Data Checks"     (exported from R CHECK_DEFS)
  <spec_inputs>/required.csv          -> "Required" flag in "Source Variables" (from R SOURCE_SPECS)
Usage: python3 specs/build_spec.py <spec_inputs_dir>
"""
import csv, sys, datetime
from openpyxl import Workbook
