TODAY = datetime.date.today().isoformat()

def rcsv(p):
    with open(p, newline="") as f: return list(csv.DictReader(f))

sched = rcsv("config/visit_schedule.csv")
checks = rcsv(f"{INP}/checks.csv")
required = {(r["FILE"], r["VAR"]) for r in rcsv(f"{INP}/required.csv")}

