# --------------------------------------------------------------------------- Derivation rules
RULES = [
 ["DR-001","Visit status","First matching rule, evaluated as of the review date D:\n1. Subject withdrawn (WDFL) and TARGDT > WDDT -> Discontinued\n2. ENTERED and OOWFL -> Out of window\n3. ENTERED -> Complete\n4. TARGDT + WINDOW >= D -> Not yet due\n5. Visit-not-done record available (VISNDFL) -> Missed\n6. Otherwise -> Overdue / not entered (DAYSOVER = D - (TARGDT + WINDOW))","WINDOW per visit schedule","R/snapshot.R review_snapshot()","test-roundtrip (as-of), test-modules"],
 ["DR-002","Target date, window, out-of-window","TARGDT = ENRLDT for the run-in visit (ANCHOR=ENRLDT); otherwise ANCHDT + 7 x NOMWK. VISOFF = VISDT - TARGDT. OOWFL = WINDOW > 0 and |VISOFF| > WINDOW. Day 1 has window 0 and defines the anchor.","Visit schedule","R/derive.R","test-roundtrip (visits)"],
 ["DR-003","Treatment start and planned Day 1","TRTSDT = first EXSTDAT per subject. Before first dose is recorded, visits anchor on PLANDY1 = ENRLDT + 56 days (8-week run-in). ANCHDT = TRTSDT, else PLANDY1.","runin_days = 56","R/derive.R","test-roundtrip (subjects)"],
 ["DR-004","Populations as of review date","DOSEDFL = first-dose record available by D. WDFL = disposition record available by D. ITTFL = DOSEDFL and AGE >= 6. 'Efficacy ITT' filter keeps ITTFL subjects; efficacy displays always use ITTFL.","itt_min_age = 6","R/snapshot.R","test-modules"],
 ["DR-005","Assessment value as of review date","Each assessment record has an availability date (IGA: EDC CREATED; MCSS: vendor TRANSDT). Corrections from the imaging vendor arrive as new rows (RECSTAT = CORRECTED). Current value = highest VERSION with AVAILDT <= D. Values display only for ENTERED visits.","","R/derive.R, R/snapshot.R","test-roundtrip (efficacy)"],
 ["DR-006","Data entry lag","ENTLAG = ENTRYDT - VISDT in days, for visits done and entered by D.","","R/derive.R","test-roundtrip"],
 ["DR-007","Entry lag target","A visit meets target if ENTLAG <= 5 days. Site metrics: median lag, 90th percentile (type 1), % within target.","lag_target = 5","R/summaries.R site_summary()","test-modules"],
 ["DR-008","Dosing compliance","COMPPCT = round(100 x (DOSPRESC - DOSMISS) / DOSPRESC) per diary interval. Latest interval per subject drives flags. Flag when COMPPCT < threshold (default 80%, user adjustable).","comp_threshold = 80","R/derive.R, R/summaries.R","test-roundtrip (compliance)"],
 ["DR-009","PK result handling","BLQFL when PCORRES begins with '<'. AVAL = numeric PCORRES, missing when BLQ (plotted at LLOQ/2 only). PCTLIM = 100 x AVAL / 2.0. PK alert when AVAL >= alert threshold (default 1.5 ng/mL, user adjustable). Exposure threshold reference line 2.0 ng/mL.","lloq = 0.1; pk_limit = 2.0; pk_alert = 1.5","R/derive.R, mod_safety.R","test-roundtrip (PK)"],
 ["DR-010","AE derivations","ARELFL = AEREL in (POSSIBLY RELATED, RELATED). ASTDY = AESTDT - TRTSDT + 1 when on/after first dose, else AESTDT - TRTSDT (no day 0). Coding as of D: if AECODDT <= D use AEDECOD/AESOC, else display 'Uncoded: <verbatim>'.","related_terms","R/derive.R, R/snapshot.R","test-roundtrip (AEs)"],
 ["DR-011","Change log","Window (since, D]. New visit: ENTRYDT in window. Corrected assessment: VERSION > 1 with AVAILDT in window for a visit entered on/before 'since'. New AE: ENTRYDT in window. Changed AE: UPDDT in window and ENTRYDT on/before 'since'. New PK: AVAILDT in window. New query: OPENDT in window. Priority: SAE (serious AE) > PK alert > Review (IGA < 0 or severe AE) > Low compliance > none; then newest first.","","R/snapshot.R change_log()","test-modules"],
 ["DR-012","IGA / MCSS summary by visit","Mean and two-sided 95% CI (t distribution, n-1 df) per visit over ITTFL subjects with ENTERED visits. Visits with n < 3 are not displayed.","min_n = 3","R/summaries.R visit_mean_ci()","test-modules"],
 ["DR-013","Efficacy subject flags","Latest post-baseline visit with IGA. % change MCSS = 100 x (latest - baseline) / baseline. Flags (first match): Worsening (IGA < 0); Run-in instability (|baseline MCSS - run-in MCSS| > 3); No response (IGA <= 0).","","R/summaries.R efficacy_subjects()","test-modules"],
 ["DR-014","Site status","Score = 2 x (median entry lag > 5 d) + 2 x (any overdue visit) + (any missed visit) + (>= 3 unresolved queries) + (any subject below compliance threshold) + (% complete in window < 85). Needs attention >= 3; Watch 1-2; On track 0.","lag_target = 5","R/summaries.R site_summary()","test-modules"],
 ["DR-015","Attention panel","Counts: new SAEs in window; PK samples >= alert (all-time); subjects with latest IGA < 0; subjects with latest compliance < threshold; visits overdue > 14 days; open queries > 30 days; sites with median lag > 5 days; AEs awaiting coding.","overdue_flag_days = 14; query_old_days = 30","R/summaries.R attention_items()","test-modules"],
 ["DR-016","Query status as of review date","Closed if CLOSEDT <= D; Answered if ANSWERDT <= D; otherwise Open. AGEDAYS = D - OPENDT for unresolved queries. QRYSTATUS in the extract is informational only.","","R/snapshot.R","test-modules"],
 ["DR-017","As-of visibility","A record is visible only when its availability date <= review date D (DMAVDT, TRTAVDT, WDAVDT, ENTRYDT, AVAILDT, OPENDT). In production D = extract date; in the demo, D is user-selected to replay weekly refreshes.","default_asof","R/snapshot.R review_snapshot()","test-roundtrip (as-of)"],
]

